import {parseDate} from '../environment/service.mjs';
export class TrafficDataService{
  constructor(repository){this.repository=repository;}
  async getTransitValue(latitude,longitude,date,{temporalMode='exact'}={}){if(![latitude,longitude].every(Number.isFinite)||Math.abs(latitude)>90||Math.abs(longitude)>180)return {status:'invalid_coordinate',value:null};const d=parseDate(date);if(!d)return {status:'invalid_date',value:null};try{const m=await this.repository.open(),common={variable:'ais_transits',datasetId:m.id,datasetRevision:m.revision,requested:{latitude,longitude,date,temporalMode},units:'annual transits per original projected source cell',time:'2025',sourceInterval:{start:m.period.start,end:m.period.end,evidence:'provider product metadata; no TIFF time axis'},source:m.source,uncertainty:{value:null,units:'transits',status:'not_provided'},quality:m.quality,assessment:'annual background transit pressure; not live density, ship speed or collision probability'};if(temporalMode!=='annual-background')return {...common,status:'explicit_annual_background_selection_required',value:null};if(new Date(d.stamp).getUTCFullYear()!==m.year)return {...common,status:'date_unavailable',value:null,availableYears:[m.year]};return {...common,...await this.repository.getCell(latitude,longitude)};}catch(e){return {status:'data_unavailable',reason:e.message,value:null};}}
}
